module freq_divbyodd(
    input clk, 
    input rst_n, 
    output clk_div
);
// Parameter declaration
parameter NUM_DIV = 5;
// Internal signal declaration
integer i;
reg [31:0] cnt1 = 0;
reg [31:0] cnt2 = 0;
reg clk_div1 = 0;
reg clk_div2 = 0;
// Behavioral modeling
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        cnt1 <= 0;
        cnt2 <= 0;
        clk_div1 <= 0;
        clk_div2 <= 0;
    end else begin
        if(cnt1 == ((NUM_DIV/2)-1)) begin
            cnt1 <= 0;
            clk_div1 <= ~clk_div1;
        end else begin
            cnt1 <= cnt1 + 1;
        end

        if(cnt2 == ((NUM_DIV/2)-1)) begin
            cnt2 <= 0;
            clk_div2 <= ~clk_div2;
        end else begin
            cnt2 <= cnt2 + 1;
        end
    end
end
assign clk_div = clk_div1 | clk_div2;
endmodule
